-- Apply with psql -X -v ON_ERROR_STOP=1. Atomic schema creation for an empty PostgreSQL 15 database.
BEGIN;
SET LOCAL lock_timeout = '3s';
CREATE EXTENSION btree_gist;
CREATE TABLE market(code varchar(20) PRIMARY KEY,name varchar(100) NOT NULL,country_code char(2) NOT NULL,currency char(3) NOT NULL,timezone varchar(50) NOT NULL);
CREATE TABLE trading_calendar(market_code varchar(20) NOT NULL REFERENCES market(code),trade_date date NOT NULL,is_trading_day boolean NOT NULL,opens_at timestamptz,closes_at timestamptz,source varchar(100) NOT NULL,collected_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(market_code,trade_date),CHECK((is_trading_day AND opens_at IS NOT NULL AND closes_at IS NOT NULL AND opens_at<closes_at) OR (NOT is_trading_day AND opens_at IS NULL AND closes_at IS NULL)));
CREATE TABLE market_index(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,index_key varchar(80) NOT NULL UNIQUE,name varchar(120) NOT NULL,kind varchar(16) NOT NULL CHECK(kind IN('MARKET','SECTOR','OTHER')),public_benchmark_code varchar(30) UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stock(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,market_code varchar(20) NOT NULL REFERENCES market(code),ticker varchar(30) NOT NULL,name varchar(200) NOT NULL,currency char(3) NOT NULL,sector_index_id bigint REFERENCES market_index(id),status varchar(20) NOT NULL CHECK(status IN('ACTIVE','DELISTED','SUSPENDED','UNKNOWN')),UNIQUE(market_code,ticker),UNIQUE(id,market_code));
CREATE INDEX idx_stock_sector ON stock(sector_index_id);
CREATE TABLE stock_risk_status(stock_id bigint PRIMARY KEY REFERENCES stock(id),status varchar(30) NOT NULL,source varchar(100) NOT NULL,collected_at timestamptz NOT NULL);
CREATE TABLE index_series(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,index_id bigint NOT NULL REFERENCES market_index(id),provider varchar(50) NOT NULL,provider_namespace varchar(80) NOT NULL,provider_series_code varchar(100) NOT NULL,calendar_market_code varchar(20) NOT NULL REFERENCES market(code),return_basis varchar(20) NOT NULL CHECK(return_basis IN('PRICE','TOTAL_RETURN')),dividend_basis varchar(10) NOT NULL CHECK(dividend_basis IN('NONE','GROSS','NET')),currency char(3) NOT NULL,is_canonical boolean NOT NULL DEFAULT false,UNIQUE(provider,provider_namespace,provider_series_code,return_basis,dividend_basis,currency),CHECK((return_basis='PRICE' AND dividend_basis='NONE') OR (return_basis='TOTAL_RETURN' AND dividend_basis IN('GROSS','NET'))));
CREATE INDEX idx_index_series_index ON index_series(index_id);
CREATE INDEX idx_index_series_calendar_market ON index_series(calendar_market_code);
CREATE UNIQUE INDEX uq_index_series_canonical ON index_series(index_id,return_basis,dividend_basis,currency) WHERE is_canonical;
CREATE TABLE index_daily(series_id bigint NOT NULL REFERENCES index_series(id),trade_date date NOT NULL,open_value numeric(19,4),high_value numeric(19,4),low_value numeric(19,4),close_value numeric(19,4),volume bigint CHECK(volume>=0),trading_amount numeric(25,2),price_status varchar(20) NOT NULL CHECK(price_status IN('FINAL','PROVISIONAL','INCOMPLETE')),price_source varchar(100) NOT NULL,collected_at timestamptz NOT NULL,advance_count integer,decline_count integer,unchanged_count integer,supply_status varchar(20) CHECK(supply_status IN('FINAL','PROVISIONAL','INCOMPLETE')),supply_source varchar(100),supply_collected_at timestamptz,PRIMARY KEY(series_id,trade_date));
CREATE INDEX idx_index_daily_date ON index_daily(trade_date,series_id);
CREATE TABLE index_constituent(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,index_id bigint NOT NULL REFERENCES market_index(id),stock_id bigint NOT NULL REFERENCES stock(id),valid_from date NOT NULL,valid_to date,weight_percent numeric(12,6),CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK(weight_percent IS NULL OR weight_percent BETWEEN 0 AND 100),EXCLUDE USING gist(index_id WITH =,stock_id WITH =,daterange(valid_from,valid_to,'[)') WITH &&));
CREATE INDEX idx_index_constituent_stock ON index_constituent(stock_id);
CREATE TABLE exchange_rate(base_currency char(3) NOT NULL,quote_currency char(3) NOT NULL,trade_date date NOT NULL,rate numeric(19,8) NOT NULL CHECK(rate>0),source varchar(100) NOT NULL,collected_at timestamptz NOT NULL,PRIMARY KEY(base_currency,quote_currency,trade_date),CHECK(base_currency<>quote_currency));
CREATE TABLE dividend_event(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,stock_id bigint NOT NULL REFERENCES stock(id),provider varchar(50) NOT NULL,provider_event_key varchar(150) NOT NULL,ex_date date NOT NULL,record_date date,payment_date date,amount_per_share numeric(19,6) NOT NULL CHECK(amount_per_share>=0),currency char(3) NOT NULL,collected_at timestamptz NOT NULL,UNIQUE(provider,provider_event_key));
CREATE INDEX idx_dividend_stock_ex_date ON dividend_event(stock_id,ex_date);
CREATE TABLE stock_price_daily(stock_id bigint NOT NULL REFERENCES stock(id),trade_date date NOT NULL,quote_scope varchar(20) NOT NULL CHECK(quote_scope IN('KRX','NXT','UNIFIED','REGULAR','EXTENDED')),open_price numeric(19,4),high_price numeric(19,4),low_price numeric(19,4),close_price numeric(19,4),volume bigint CHECK(volume>=0),trading_amount numeric(25,2),data_status varchar(20) NOT NULL CHECK(data_status IN('FINAL','PROVISIONAL','INCOMPLETE')),source varchar(100) NOT NULL,collected_at timestamptz NOT NULL,revision integer NOT NULL DEFAULT 1 CHECK(revision>=1),corrected_at timestamptz,PRIMARY KEY(stock_id,trade_date,quote_scope),CHECK(data_status<>'FINAL' OR (open_price IS NOT NULL AND high_price IS NOT NULL AND low_price IS NOT NULL AND close_price IS NOT NULL)),CHECK(high_price IS NULL OR low_price IS NULL OR high_price>=low_price),CHECK(high_price IS NULL OR open_price IS NULL OR high_price>=open_price),CHECK(high_price IS NULL OR close_price IS NULL OR high_price>=close_price),CHECK(low_price IS NULL OR open_price IS NULL OR low_price<=open_price),CHECK(low_price IS NULL OR close_price IS NULL OR low_price<=close_price),CHECK(open_price IS NULL OR open_price>=0),CHECK(high_price IS NULL OR high_price>=0),CHECK(low_price IS NULL OR low_price>=0),CHECK(close_price IS NULL OR close_price>=0));
CREATE INDEX idx_stock_price_history ON stock_price_daily(stock_id,quote_scope,trade_date DESC);
CREATE INDEX idx_stock_price_sweep ON stock_price_daily(trade_date,quote_scope,stock_id);
CREATE TABLE stock_price_adjustment(stock_id bigint NOT NULL,trade_date date NOT NULL,quote_scope varchar(20) NOT NULL,adjustment_basis varchar(30) NOT NULL CHECK(adjustment_basis='PROVIDER_ADJUSTED'),adjustment_as_of date NOT NULL,open_price numeric(19,4),high_price numeric(19,4),low_price numeric(19,4),adjusted_close numeric(19,4) NOT NULL,source varchar(100) NOT NULL,collected_at timestamptz NOT NULL,PRIMARY KEY(stock_id,trade_date,quote_scope),FOREIGN KEY(stock_id,trade_date,quote_scope) REFERENCES stock_price_daily(stock_id,trade_date,quote_scope),CHECK(high_price IS NULL OR low_price IS NULL OR high_price>=low_price),CHECK(adjustment_as_of>=trade_date));
CREATE TABLE stock_investor_trade_daily(stock_id bigint NOT NULL REFERENCES stock(id),trade_date date NOT NULL,quote_scope varchar(20) NOT NULL,investor_type varchar(30) NOT NULL CHECK(investor_type IN('FOREIGN','INSTITUTION_TOTAL','INDIVIDUAL','FINANCIAL_INVESTMENT','INSURANCE','TRUST','PRIVATE_FUND','BANK','PENSION','OTHER')),net_quantity numeric(19,6),net_amount numeric(25,2),data_status varchar(20) NOT NULL CHECK(data_status IN('FINAL','PROVISIONAL','INCOMPLETE')),source varchar(100) NOT NULL,collected_at timestamptz NOT NULL,PRIMARY KEY(stock_id,trade_date,quote_scope,investor_type),CHECK(data_status<>'FINAL' OR (net_quantity IS NOT NULL AND net_amount IS NOT NULL)));
CREATE INDEX idx_investor_rank ON stock_investor_trade_daily(trade_date,quote_scope,investor_type,net_amount DESC,stock_id);
CREATE TABLE stock_technical_indicator(stock_id bigint NOT NULL,trade_date date NOT NULL,quote_scope varchar(20) NOT NULL,price_basis varchar(30) NOT NULL CHECK(price_basis IN('RAW','PROVIDER_ADJUSTED')),ma5 numeric(19,4),ma20 numeric(19,4),ma20_disparity numeric(12,6),ma60 numeric(19,4),ma120 numeric(19,4),rsi14 numeric(12,6),macd numeric(19,6),macd_signal numeric(19,6),adx numeric(12,6),plus_di numeric(12,6),minus_di numeric(12,6),input_manifest jsonb NOT NULL,algorithm_version varchar(80) NOT NULL,calculated_at timestamptz NOT NULL,PRIMARY KEY(stock_id,trade_date,quote_scope,price_basis),FOREIGN KEY(stock_id,trade_date,quote_scope) REFERENCES stock_price_daily(stock_id,trade_date,quote_scope));
CREATE TABLE market_signal(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,stock_id bigint NOT NULL REFERENCES stock(id),trade_date date NOT NULL,quote_scope varchar(20) NOT NULL,signal_type varchar(50) NOT NULL,rule_version varchar(80) NOT NULL,input_manifest jsonb NOT NULL,created_at timestamptz NOT NULL,UNIQUE(stock_id,trade_date,quote_scope,signal_type,rule_version));
CREATE INDEX idx_market_signal_stock ON market_signal(stock_id,trade_date);
CREATE TABLE stock_ai_analysis(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,stock_id bigint NOT NULL REFERENCES stock(id),signal_id bigint REFERENCES market_signal(id),trade_date date NOT NULL,quote_scope varchar(20),analysis_kind varchar(40) NOT NULL,model_version varchar(100) NOT NULL,prompt_version varchar(100) NOT NULL,input_manifest jsonb NOT NULL,result jsonb NOT NULL,status varchar(20) NOT NULL CHECK(status IN('SUCCEEDED','FAILED')),generated_at timestamptz NOT NULL);
CREATE INDEX idx_stock_ai_latest ON stock_ai_analysis(stock_id,quote_scope,analysis_kind,trade_date DESC,generated_at DESC,id DESC);
CREATE INDEX idx_stock_ai_signal ON stock_ai_analysis(signal_id);
CREATE TABLE index_technical_indicator(series_id bigint NOT NULL,trade_date date NOT NULL,ma5 numeric(19,4),ma20 numeric(19,4),ma20_disparity numeric(12,6),ma60 numeric(19,4),ma120 numeric(19,4),rsi14 numeric(12,6),macd numeric(19,6),macd_signal numeric(19,6),adx numeric(12,6),plus_di numeric(12,6),minus_di numeric(12,6),input_manifest jsonb NOT NULL,algorithm_version varchar(80) NOT NULL,calculated_at timestamptz NOT NULL,PRIMARY KEY(series_id,trade_date),FOREIGN KEY(series_id,trade_date) REFERENCES index_daily(series_id,trade_date));
CREATE TABLE index_weather(series_id bigint NOT NULL REFERENCES index_series(id),trade_date date NOT NULL,score numeric(6,2) NOT NULL CHECK(score BETWEEN 0 AND 100),status varchar(24) NOT NULL,score_version varchar(80) NOT NULL,input_manifest jsonb NOT NULL,calculated_at timestamptz NOT NULL,PRIMARY KEY(series_id,trade_date));
CREATE TABLE index_ai_analysis(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,series_id bigint NOT NULL REFERENCES index_series(id),trade_date date NOT NULL,analysis_kind varchar(40) NOT NULL,model_version varchar(100) NOT NULL,prompt_version varchar(100) NOT NULL,input_manifest jsonb NOT NULL,result jsonb NOT NULL,status varchar(20) NOT NULL CHECK(status IN('SUCCEEDED','FAILED')),generated_at timestamptz NOT NULL);
CREATE INDEX idx_index_ai_latest ON index_ai_analysis(series_id,analysis_kind,trade_date DESC,generated_at DESC,id DESC);
CREATE TABLE sector_leading_stock(series_id bigint NOT NULL,trade_date date NOT NULL,rank smallint NOT NULL CHECK(rank BETWEEN 1 AND 5),stock_id bigint NOT NULL,price_date date NOT NULL,quote_scope varchar(20) NOT NULL,PRIMARY KEY(series_id,trade_date,rank),UNIQUE(series_id,trade_date,stock_id),FOREIGN KEY(series_id,trade_date) REFERENCES index_daily(series_id,trade_date),FOREIGN KEY(stock_id,price_date,quote_scope) REFERENCES stock_price_daily(stock_id,trade_date,quote_scope),CHECK(price_date<=trade_date));
CREATE INDEX idx_sector_leading_stock_stock ON sector_leading_stock(stock_id,trade_date);
CREATE TABLE member(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nickname varchar(40) NOT NULL UNIQUE,role varchar(20) NOT NULL CHECK(role IN('USER','ADMIN')),risk_level varchar(20) CHECK(risk_level IN('LOW','MEDIUM','HIGH')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz);
CREATE TABLE member_identity(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,member_id bigint NOT NULL REFERENCES member(id),provider varchar(30) NOT NULL,subject varchar(200) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,subject));
CREATE INDEX idx_member_identity_member ON member_identity(member_id);
CREATE TABLE portfolio(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,member_id bigint NOT NULL REFERENCES member(id),name varchar(100) NOT NULL,configuration_version bigint NOT NULL DEFAULT 0 CHECK(configuration_version BETWEEN 0 AND 9007199254740991),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz,UNIQUE(member_id,id));
CREATE INDEX idx_portfolio_member ON portfolio(member_id,id);
CREATE TABLE portfolio_item(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,portfolio_id bigint NOT NULL REFERENCES portfolio(id),stock_id bigint REFERENCES stock(id),asset_type varchar(12) NOT NULL CHECK(asset_type IN('STOCK','CASH')),purchase_date date,quantity numeric(19,6),average_purchase_price numeric(19,4),target_weight numeric(12,6) CHECK(target_weight BETWEEN 0 AND 100),CHECK((asset_type='STOCK' AND stock_id IS NOT NULL AND quantity IS NOT NULL AND quantity>=0 AND average_purchase_price IS NOT NULL AND purchase_date IS NOT NULL) OR (asset_type='CASH' AND stock_id IS NULL)));
CREATE INDEX idx_portfolio_item_portfolio ON portfolio_item(portfolio_id);
CREATE INDEX idx_portfolio_item_stock ON portfolio_item(stock_id);
CREATE TABLE portfolio_stats(portfolio_id bigint PRIMARY KEY REFERENCES portfolio(id),base_date date NOT NULL,window_start date,price_basis varchar(30) NOT NULL,configuration_version bigint NOT NULL,input_manifest jsonb NOT NULL,beta numeric(12,6),mdd numeric(12,6),sharpe_ratio numeric(12,6),calculated_at timestamptz NOT NULL);
CREATE TABLE portfolio_ai_report(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,portfolio_id bigint NOT NULL REFERENCES portfolio(id),model_version varchar(100) NOT NULL,prompt_version varchar(100) NOT NULL,input_manifest jsonb NOT NULL,result jsonb NOT NULL,generated_at timestamptz NOT NULL);
CREATE INDEX idx_portfolio_ai_latest ON portfolio_ai_report(portfolio_id,generated_at DESC,id DESC);
CREATE TABLE actual_account(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,member_id bigint NOT NULL REFERENCES member(id),name varchar(100) NOT NULL,base_currency char(3) NOT NULL,version bigint NOT NULL DEFAULT 0 CHECK(version BETWEEN 0 AND 9007199254740991),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(member_id,id));
CREATE INDEX idx_actual_account_member ON actual_account(member_id,id);
CREATE TABLE actual_mutation_receipt(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,member_id bigint NOT NULL REFERENCES member(id),response_account_id bigint,account_scope varchar(30) NOT NULL,operation varchar(30) NOT NULL,request_key varchar(200) NOT NULL,response_payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(member_id,account_scope,operation,request_key),FOREIGN KEY(member_id,response_account_id) REFERENCES actual_account(member_id,id));
CREATE TABLE watchlist_group(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,member_id bigint NOT NULL REFERENCES member(id),name varchar(100) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX idx_watchlist_group_member ON watchlist_group(member_id,id);
CREATE TABLE watchlist_item(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,watchlist_group_id bigint NOT NULL REFERENCES watchlist_group(id),stock_id bigint NOT NULL REFERENCES stock(id),note varchar(200),created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE UNIQUE INDEX uq_watchlist_item_active ON watchlist_item(watchlist_group_id,stock_id) WHERE deleted_at IS NULL;
CREATE INDEX idx_watchlist_item_stock ON watchlist_item(stock_id);
CREATE TABLE outbox_event(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,topic varchar(255) NOT NULL,payload jsonb NOT NULL,status varchar(20) NOT NULL CHECK(status IN('PENDING','PROCESSING','PUBLISHED','FAILED')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),available_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,error_message text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_outbox_pending ON outbox_event(available_at,id) WHERE status='PENDING';
COMMIT;
